candidates.raw:
    unint32 mask = 0U;
    size_t i;
    double d[3];
    double out[3];
    double fs = full_scale_a_m2;

    if ((requested_a_m2 == NULL) || (duty == NULL))
        return ADCS_E_NULL;

    duty->command.x = 0.0;
    duty->command.y = 0.0;
    duty->command.z = 0.0;
    duty->saturated_axes = 0U;

    if ((!adcs_is_finite_vec3(requested_a_m2)) || (!isfinite(full_scale_a_m2)) ||
        (!isfinite(minimum_duty)) || (full_scale_a_m2 <= 0.0) || (minimum_duty < 0.0) ||
        (minimum_duty > 1.0)) {
        return ADCS_E_RANGE;
    }

    d[0] = requested_a_m2->x;
    d[1] = requested_a_m2->y;
    d[2] = requested_a_m2->z;

    for (i = 0; i < 3U; i++) {
        double norm_d = d[i] / fs;
        double mag = fabs(norm_d);
        double sel;
        if (mag == 0.0) {
            sel = 0.0;
        } else if (mag < minimum_duty) {
            sel = minimum_duty;
            mask |= (unint32)(1U << i);
        } else if (mag <= 1.0) {
            sel = mag;
        } else {
            sel = 1.0;
        }
        out[i] = copysign(sel, norm_d);
    }

    duty->command.x = out[0];
    duty->command.y = out[1];
    duty->command.z = out[2];
    duty->saturated_axes = mask;
    return ADCS_OK;
}

