    size_t i;
    double comp[3];
    double d, mag, out_mag;
    unint32 promote = 0U;
    adcs_vec3_t zero = {0.0, 0.0, 0.0};

    if ((requested_a_m2 == NULL) || (duty == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!isfinite(full_scale_a_m2)) || (full_scale_a_m2 <= 0.0) ||
        (!isfinite(minimum_duty)) || (minimum_duty < 0.0) || (minimum_duty > 1.0) ||
        (!adcs_is_finite_vec3(requested_a_m2))) {
        duty->command = zero;
        duty->saturated_axes = 0U;
        return ADCS_E_RANGE;
    }

    comp[0] = requested_a_m2->x;
    comp[1] = requested_a_m2->y;
    comp[2] = requested_a_m2->z;

    for (i = 0; i < 3U; i++) {
        d = comp[i] / full_scale_a_m2;
        mag = fabs(d);
        if (mag == 0.0) {
            out_mag = 0.0;
        } else if (mag < minimum_duty) {
            out_mag = minimum_duty;
            promote |= (unint32)(1U << i);
        } else if (mag <= 1.0) {
            out_mag = mag;
        } else {
            out_mag = 1.0;
        }
        if (d < 0.0) {
            out_mag = -out_mag;
        }
        comp[i] = out_mag;
    }

    duty->command = (adcs_vec3_t){comp[0], comp[1], comp[2]};
    duty->saturated_axes = promote;
    return ADCS_OK;
}

